/* 학습 해설
 * 두 필드64비트 시간·itimerspec의 값과 간격
 * 초를64비트로 저장하는 시간 구조체와 반복 타이머 설정 구조를 배웁니다.
 * time64_t는 __s64,timeu64_t는 __u64입니다. timespec64는 time64_t tv_sec와 long tv_nsec이고 itimerspec64는 it_interval·it_value 두 timespec64를 담습니다. 초 폭이64비트라는 점과 나노초 부분·유효 날짜 정책·전체 scalar ktime 표현 범위는 별도입니다.
 * 정규화된 초·나노초 필드를 사용하고 타이머 초기 만료값과 반복 간격의 의미를 구분합니다. 구조체 선언만으로 timer가 등록되거나 현재 시간을 읽는 작업이 수행되지는 않습니다.
 */
struct timespec64 {
	time64_t	tv_sec;			/* seconds */
	long		tv_nsec;		/* nanoseconds */
};

struct itimerspec64 {
	struct timespec64 it_interval;
	struct timespec64 it_value;
};

/* Parameters used to convert the timespec values: */
#define PSEC_PER_NSEC			1000L

/* Located here for timespec[64]_valid_strict */
#define TIME64_MAX			((s64)~((u64)1 << 63))
#define TIME64_MIN			(-TIME64_MAX - 1)

#define KTIME_MAX			((s64)~((u64)1 << 63))
#define KTIME_MIN			(-KTIME_MAX - 1)
#define KTIME_SEC_MAX			(KTIME_MAX / NSEC_PER_SEC)
#define KTIME_SEC_MIN			(KTIME_MIN / NSEC_PER_SEC)

/*
 * Limits for settimeofday():
 *
 * To prevent setting the time close to the wraparound point time setting
 * is limited so a reasonable uptime can be accomodated. Uptime of 30 years
 * should be really sufficient, which means the cutoff is 2232. At that
 * point the cutoff is just a small part of the larger problem.
 */

/* 학습 해설
 * 시간 범위 상수·ktime과 settimeofday의 여유
 * 시각 설정 한계를 scalar wrap 직전까지 허용하지 않는 uptime 여유 정책을 배웁니다.
 * TIME64와 KTIME MAX/MIN은 signed64 경계이고 KTIME_SEC_MAX/MIN은 ns당 초 상수로 나눈 경계입니다. TIME_UPTIME_SEC_MAX는30*365일을 초로 환산하고 TIME_SETTOD_SEC_MAX는 ktime 초 상한에서 그 여유를 뺍니다. setter valid predicate는 이 더 작은 경계를 검사합니다.
 * 기본 시간 표현·strict ktime 표현·CLOCK_REALTIME 설정 가능 범위를 구분합니다. 고정 v6.12의 정책 상수와 주석의 예상 연도 설명을 모든 OS의 법칙이나 현재 사용자 날짜 설정 권고로 확대하지 않습니다.
 */
static inline bool timespec64_valid_settod(const struct timespec64 *ts)
{
	if (!timespec64_valid(ts))
		return false;
	/* Disallow values which cause overflow issues vs. CLOCK_REALTIME */
	if ((unsigned long long)ts->tv_sec >= TIME_SETTOD_SEC_MAX)
		return false;
	return true;
}

/**
 * timespec64_to_ns - Convert timespec64 to nanoseconds
 * @ts:		pointer to the timespec64 variable to be converted
 *
 * Returns the scalar nanosecond representation of the timespec64
 * parameter.
 */
static inline s64 timespec64_to_ns(const struct timespec64 *ts)
{
	/* Prevent multiplication overflow / underflow */
	if (ts->tv_sec >= KTIME_SEC_MAX)
		return KTIME_MAX;

	if (ts->tv_sec <= KTIME_SEC_MIN)
		return KTIME_MIN;

/* 학습 해설
 * timespec 비교·초 우선과 정규화된 나노초 차
 * 두 필드 시간을 사전식으로 비교하고 정상 나노초 범위가 반환폭을 지지하는 이유를 배웁니다.
 * equal은 초와 나노초가 둘 다 같은지 검사합니다. compare는 초 대소가 다르면 -1/1이고 같으면 tv_nsec 차이를 int로 반환합니다. 정상 ns0..999999999에서는 차이가 int32 범위에 들어갑니다. 반환은 부호 의미이며 ktime_compare처럼 항상 세 값만인 것은 아닙니다.
 * 정규화된 입력을 같은 clock 의미에서 비교합니다. 임의 거대한 long nsec를 넣어 int 차이의 정상 범위를 보장하지 않습니다. compare 결과의 부호로 순서를 판단합니다.
 */
static inline int timespec64_compare(const struct timespec64 *lhs, const struct timespec64 *rhs)
{
	if (lhs->tv_sec < rhs->tv_sec)
		return -1;
	if (lhs->tv_sec > rhs->tv_sec)
		return 1;
	return lhs->tv_nsec - rhs->tv_nsec;
}

extern void set_normalized_timespec64(struct timespec64 *ts, time64_t sec, s64 nsec);

static inline struct timespec64 timespec64_add(struct timespec64 lhs,
						struct timespec64 rhs)
{
	struct timespec64 ts_delta;
	set_normalized_timespec64(&ts_delta, lhs.tv_sec + rhs.tv_sec,
				lhs.tv_nsec + rhs.tv_nsec);
	return ts_delta;
}

/*
 * sub = lhs - rhs, in normalized form
 */
static inline struct timespec64 timespec64_sub(struct timespec64 lhs,
						struct timespec64 rhs)
{

/* 학습 해설
 * timespec 합·차 정규화·borrow와 carry
 * 나노초 필드가1초를 넘거나 음수가 되면 초로 옮기는 원리를 배웁니다.
 * add/sub는 초·나노초를 각각 더하거나 뺀 뒤 set_normalized_timespec64에 넘깁니다. time.c helper는 nsec>=10^9이면 초를 늘리고10^9를 빼며 nsec<0이면 초를 줄이고10^9를 더합니다. 결과 ns는 항상0..10^9-1입니다. 기본 필드 산술의 overflow는 별도로 확인해야 합니다.
 * 범위 안의 normalized 입력에서 carry·borrow를 표로 계산합니다. 예를 들어1초100ns에서200ns를 빼면0초999999900ns입니다. helper의 empty asm은 반복을 modulo로 바꾸는 최적화를 제한하려는 구현 장치입니다.
 */
static inline struct timespec64 timespec64_add(struct timespec64 lhs,
						struct timespec64 rhs)
{
	struct timespec64 ts_delta;
	set_normalized_timespec64(&ts_delta, lhs.tv_sec + rhs.tv_sec,
				lhs.tv_nsec + rhs.tv_nsec);
	return ts_delta;
}

/*
 * sub = lhs - rhs, in normalized form
 */
static inline struct timespec64 timespec64_sub(struct timespec64 lhs,
						struct timespec64 rhs)
{
	struct timespec64 ts_delta;
	set_normalized_timespec64(&ts_delta, lhs.tv_sec - rhs.tv_sec,
				lhs.tv_nsec - rhs.tv_nsec);
	return ts_delta;
}

/*
 * Returns true if the timespec64 is norm, false if denorm:
 */
static inline bool timespec64_valid(const struct timespec64 *ts)
{

/* 학습 해설
 * timespec valid의 세 정책·음수 날짜와 ns 범위
 * 정규화된 음수 표현을 지원하는 것과 특정 API가 그 날짜를 허용하는 것은 다른 점을 배웁니다.
 * valid는 tv_sec<0을 false로 하고 tv_nsec를 unsigned long으로 보아>=10^9이면 false입니다. negative nsec도 unsigned 변환으로 그 범위를 벗어납니다. strict는 valid 뒤 초>=KTIME_SEC_MAX를 거절하고 settod는 더 작은 TIME_SETTOD_SEC_MAX를 거절합니다.
 * 실제 호출 용도의 predicate를 선택하고 기본 valid 통과만으로 모든 scalar 변환·clock 설정이 가능하다고 가정하지 않습니다. ns_to_timespec64의 정상 음수 표현과 날짜 정책 거절을 함께 설명합니다.
 */
static inline bool timespec64_valid(const struct timespec64 *ts)
{
	/* Dates before 1970 are bogus */
	if (ts->tv_sec < 0)
		return false;
	/* Can't have more nanoseconds then a second */
	if ((unsigned long)ts->tv_nsec >= NSEC_PER_SEC)
		return false;
	return true;
}

static inline bool timespec64_valid_strict(const struct timespec64 *ts)
{
	if (!timespec64_valid(ts))
		return false;
	/* Disallow values that could overflow ktime_t */
	if ((unsigned long long)ts->tv_sec >= KTIME_SEC_MAX)
		return false;
	return true;
}

static inline bool timespec64_valid_settod(const struct timespec64 *ts)
{
	if (!timespec64_valid(ts))
		return false;
	/* Disallow values which cause overflow issues vs. CLOCK_REALTIME */

/* 학습 해설
 * timespec64의 ns scalar·양·음수 보수 포화
 * 두 필드를 나노초 하나로 만들 때 곱의 양끝 경계를 제한하는 정책을 배웁니다.
 * to_ns는 sec>=KTIME_SEC_MAX이면 KTIME_MAX,sec<=KTIME_SEC_MIN이면 KTIME_MIN을 반환하고 그 사이에서는 sec*10^9+nsec입니다. 초 경계만으로 보수 clamp하므로 모든 boundary ns 조합의 exact 값 계산과는 다릅니다. normalized nsec와 sane 초 범위를 사용합니다.
 * 음수까지 변환하려면 이 함수의 양·음수 clamp와 ktime_set의 다른 조건을 비교합니다. arbitrary 큰 nsec 입력까지 자동 안전 검사하는 API로 확대하지 않습니다.
 */
static inline s64 timespec64_to_ns(const struct timespec64 *ts)
{
	/* Prevent multiplication overflow / underflow */
	if (ts->tv_sec >= KTIME_SEC_MAX)
		return KTIME_MAX;

	if (ts->tv_sec <= KTIME_SEC_MIN)
		return KTIME_MIN;

	return ((s64) ts->tv_sec * NSEC_PER_SEC) + ts->tv_nsec;
}

/**
 * ns_to_timespec64 - Convert nanoseconds to timespec64
 * @nsec:	the nanoseconds value to be converted
 *
 * Returns the timespec64 representation of the nsec parameter.
 */
extern struct timespec64 ns_to_timespec64(s64 nsec);

/**
 * timespec64_add_ns - Adds nanoseconds to a timespec64
 * @a:		pointer to timespec64 to be incremented
 * @ns:		unsigned nanoseconds value to be added
 *
 * This must always be inlined because its used from the x86-64 vdso,
 * which cannot call other kernel functions.
 */

/* 학습 해설
 * timespec에 unsigned ns 더하기·inline VDSO 경로
 * 작은 나노초 carry를 외부 커널 함수 호출 없이 처리하는 구조를 배웁니다.
 * add_ns는 기존 tv_nsec+ns를 __iter_div_u64_rem으로10^9로 나눠 몫을 tv_sec에 더하고 나머지를 tv_nsec에 씁니다. 원본 주석은 x86-64 vdso에서 다른 kernel 함수를 호출할 수 없어 항상 inline이어야 한다고 설명합니다. unsigned 합·u32 반복 몫·초 결과의 범위도 지켜야 합니다.
 * 정규화된 입력과 합 범위·작은 예상 carry에 사용합니다. iterative helper를 매우 큰 ns의 무제한 빠른 나눗셈으로 읽지 않으며 VDSO의 호출 경계를 inline 요구와 연결합니다.
 */
static __always_inline void timespec64_add_ns(struct timespec64 *a, u64 ns)
{
	a->tv_sec += __iter_div_u64_rem(a->tv_nsec + ns, NSEC_PER_SEC, &ns);
	a->tv_nsec = ns;
}

/*
 * timespec64_add_safe assumes both values are positive and checks for
 * overflow. It will return TIME64_MAX in case of overflow.
 */
extern struct timespec64 timespec64_add_safe(const struct timespec64 lhs,
					 const struct timespec64 rhs);

#endif /* _LINUX_TIME64_H */

/* 학습 해설
 * 양수 timespec 안전 합·초 overflow의 포화
 * 양수 정규화된 기간의 합이 초 범위를 넘으면 최대값 정책을 적용하는 helper를 배웁니다.
 * add_safe는 두 normalized nonnegative 값을 전제로 초를 unsigned 합으로 전달하고 nsec 합을 normalize합니다. 결과 초가 어느 입력보다 작으면 TIME64_MAX와 nsec0을 반환합니다. 이 전제 없이 음수 일반합을 넣는 정확한 checked arithmetic API가 아닙니다.
 * 양수 기간 합의 입력·컴파일 signed wrap 문맥을 확인하고 포화 결과의 의미를 caller 정책으로 처리합니다. 함수가 time.c 전체를 대표하는 것처럼 완료로 계산하지 않습니다.
 */
struct timespec64 timespec64_add_safe(const struct timespec64 lhs,
				const struct timespec64 rhs)
{
	struct timespec64 res;

	set_normalized_timespec64(&res, (timeu64_t) lhs.tv_sec + rhs.tv_sec,
			lhs.tv_nsec + rhs.tv_nsec);

	if (unlikely(res.tv_sec < lhs.tv_sec || res.tv_sec < rhs.tv_sec)) {
		res.tv_sec = TIME64_MAX;
		res.tv_nsec = 0;
	}

	return res;
}

