int get_timespec64(struct timespec64 *ts,

/* 학습 해설
 * 시간 단위 상수·밀리부터 펨토까지 형식 폭
 * 단위 배수 자체도 정수 리터럴 형식과 곱의 표현 범위를 갖는 점을 배웁니다.
 * vdso/time64.h는 MSEC_PER_SEC=1000,USEC_PER_MSEC=1000,NSEC_PER_USEC=1000,NSEC_PER_MSEC=10^6,USEC_PER_SEC=10^6,NSEC_PER_SEC=10^9,PSEC_PER_SEC=10^12,FSEC_PER_SEC=10^15를 정의합니다. 큰 ps/fs는 LL suffix이고 다른 값은 L입니다. time64.h의 PSEC_PER_NSEC=1000도 연결됩니다.
 * 숫자 단위와 정수 폭을 맞춰 변환하고 작은 ns를 ms로 나누는 것과 큰 seconds를 fs로 곱하는 범위 차이를 계산합니다. 이 constants header의 전체 guard·주석·여덟 값을 설명으로 연결합니다.
 */
static inline s64 ktime_to_ms(const ktime_t kt)
{
	return ktime_divns(kt, NSEC_PER_MSEC);
}

static inline s64 ktime_us_delta(const ktime_t later, const ktime_t earlier)
{
       return ktime_to_us(ktime_sub(later, earlier));
}

static inline s64 ktime_ms_delta(const ktime_t later, const ktime_t earlier)
{
	return ktime_to_ms(ktime_sub(later, earlier));
}

static inline ktime_t ktime_add_us(const ktime_t kt, const u64 usec)
{
	return ktime_add_ns(kt, usec * NSEC_PER_USEC);
}

static inline ktime_t ktime_add_ms(const ktime_t kt, const u64 msec)
{
	return ktime_add_ns(kt, msec * NSEC_PER_MSEC);
}

static inline ktime_t ktime_sub_us(const ktime_t kt, const u64 usec)

/* 학습 해설
 * VDSO 반복 나눗셈·몫 횟수와 나머지
 * division 명령 대신 반복 subtraction을 쓰는 helper의 사용 조건과 비용을 배웁니다.
 * helper는 dividend>=divisor 동안 divisor를 빼고 u32 ret를 늘립니다. 끝에서 나머지를 출력하고 몫을 반환합니다. empty asm은 이 루프를 modulo로 바꾸는 compiler 최적화를 막는 목적입니다. divisor0은 진행하지 않는 반복이고 몫이 u32 범위를 넘으면 그 숫자도 wrap되므로 유효한 small quotient 계약이 필요합니다.
 * 작은 carry를 처리하는 timespec_add_ns 같은 경로에서 positive divisor와 지원 몫 범위를 준비합니다. 실행 횟수는 몫에 비례하므로 큰 dividend의 범용 빠른 나눗셈으로 사용하지 않습니다.
 */
__iter_div_u64_rem(u64 dividend, u32 divisor, u64 *remainder)
{
	u32 ret = 0;

	while (dividend >= divisor) {
		/* The following asm() prevents the compiler from
		   optimising this loop into a modulo operation.  */
		asm("" : "+rm"(dividend));

		dividend -= divisor;
		ret++;
	}

	*remainder = dividend;

	return ret;
}

#if defined(CONFIG_ARCH_SUPPORTS_INT128) && defined(__SIZEOF_INT128__)

#ifndef mul_u64_u32_add_u64_shr
static __always_inline u64 mul_u64_u32_add_u64_shr(u64 a, u32 mul, u64 b, unsigned int shift)
{
	return (u64)((((unsigned __int128)a * mul) + b) >> shift);
}
#endif /* mul_u64_u32_add_u64_shr */

/* 학습 해설
 * 넓은 곱·합·이동·128비트 중간값의 역할
 * 64×32비트 곱을 shift 전에128비트로 계산해 높은 비트를 보존하는 기술을 배웁니다.
 * ARCH_SUPPORTS_INT128와 compiler __SIZEOF_INT128__가 있으면 a를 unsigned128로 만든 뒤 a*mul+b를 계산해 shift하고 u64로 반환합니다.64×32+64의 중간값은128비트에 들어갑니다. shift 뒤 반환 폭보다 큰 비트는 u64 변환으로 잘립니다. guard는 다른 아키텍처에서 같은 구현을 강제하지 않습니다.
 * 지원 shift 범위와 최종 수치 의미를 확인합니다. shared helper의 fallback까지 사용한다면 일반적으로0..32 shift 조건을 지켜 high32 구성의 음수 shift를 피합니다. 이 함수는 포화 반환 API가 아닙니다.
 */
static __always_inline u64 mul_u64_u32_add_u64_shr(u64 a, u32 mul, u64 b, unsigned int shift)
{
	return (u64)((((unsigned __int128)a * mul) + b) >> shift);
}
#endif /* mul_u64_u32_add_u64_shr */

#else

#ifndef mul_u64_u32_add_u64_shr
#ifndef mul_u32_u32
static inline u64 mul_u32_u32(u32 a, u32 b)
{
	return (u64)a * b;
}
#define mul_u32_u32 mul_u32_u32
#endif
static __always_inline u64 mul_u64_u32_add_u64_shr(u64 a, u32 mul, u64 b, unsigned int shift)
{
	u32 ah = a >> 32, al = a;
	bool ovf;
	u64 ret;

	ovf = __builtin_add_overflow(mul_u32_u32(al, mul), b, &ret);
	ret >>= shift;
	if (ovf && shift)
		ret += 1ULL << (64 - shift);

/* 학습 해설
 * 32비트 분해 곱·carry를 shift 후 복구
 * 128비트 형식이 없을 때 높은·낮은 부분과64비트 overflow carry로 같은 계산을 구성하는 방법을 배웁니다.
 * fallback은 a의 ah/al을 분리하고 al*mul+b의 u64 합 overflow를 builtin으로 기록합니다. ret를 shift한 뒤 carry가 있고 shift>0이면1<<(64-shift)를 보충합니다. ah가 있으면 ah*mul을32-shift만큼 옮겨 더합니다. 일반 지원 shift0..32에서는128비트 계산의 낮은64비트 결과와 대응합니다.
 * 일반 입력에서0<=shift<=32를 지키고 cast·carry·high part를 단계별 추적합니다. ah가 nonzero인 shift>32는32-shift의 잘못된 이동량을 만들 수 있어 무제한 지원으로 읽지 않습니다. mul_u32_u32는 곱 전에u64로 cast하는 보조 helper입니다.
 */
static __always_inline u64 mul_u64_u32_add_u64_shr(u64 a, u32 mul, u64 b, unsigned int shift)
{
	u32 ah = a >> 32, al = a;
	bool ovf;
	u64 ret;

	ovf = __builtin_add_overflow(mul_u32_u32(al, mul), b, &ret);
	ret >>= shift;
	if (ovf && shift)
		ret += 1ULL << (64 - shift);
	if (ah)
